// Aanvulling op basis van de toetsmatrijzen, rubrics en examenprogramma's van ExTH (examendocumenten, november 2026).
// Formaat: [categorie, vraag, [JUIST, fout, fout, fout], uitleg, bron, vaste code]. Welke toetsterm bij welke vraag hoort, staat in matrijs.js.
const Q7 = [
// ---------- OPSPORINGSAMBTENAAR EN BOA ----------
["boa", "Wie is de toezichthouder op een boa die in een arrondissement werkzaam is?", ["De hoofdofficier van justitie van dat arrondissementsparket.", "De korpschef van de politie.", "De burgemeester van de gemeente waar de boa zijn werkzaamheden uitvoert.", "De minister van Justitie en Veiligheid."], "Het toezicht op de boa is verdeeld. De toezichthouder is de hoofdofficier van justitie van het arrondissement (bij een landelijke boa: het functioneel of landelijk parket). De korpschef van de politie is de direct toezichthouder.", "art. 36 en 38 Besluit boa", "qtuht9x"],
["boa", "Wie is de direct toezichthouder op een boa?", ["De korpschef van de politie, eventueel via mandaat aan de politiechef.", "De hoofdofficier van justitie van het arrondissement.", "De werkgever van de boa of diens leidinggevende.", "De burgemeester van de gemeente waar de boa in dienst is getreden, als hoofd van de politie."], "De korpschef van de politie is direct toezichthouder (vaak gemandateerd aan de politiechef van de eenheid). Hij ziet toe op het juist uitvoeren van de opsporingsbevoegdheden, de samenwerking met de politie en de opleiding door de werkgever.", "art. 36 en 39 Besluit boa", "q18i8ltv"],
["boa", "Welke verplichting heeft de werkgever van een boa tegenover de toezichthouder en de direct toezichthouder?", ["Hij verschaft hun alle gewenste informatie over de boa's in zijn dienst.", "Hij laat elk proces-verbaal van de boa vooraf door hen controleren en ondertekenen.", "Hij vraagt hun toestemming voor elk rooster van de boa.", "Hij meldt alleen klachten die tot een veroordeling hebben geleid."], "De werkgever heeft een informatieplicht: hij verschaft de toezichthouder en de direct toezichthouder alle door hen gewenste informatie over de buitengewoon opsporingsambtenaren in zijn dienst.", "art. 41 Besluit boa", "qe10jf6"],
["boa", "Waar is geregeld dat de politie en de boa met elkaar samenwerken?", ["In artikel 10 van de Politiewet 2012.", "In artikel 1 van de Algemene wet op het binnentreden.", "In artikel 5:20 van de Algemene wet bestuursrecht.", "In artikel 70 van de Wet personenvervoer 2000."], "Artikel 10 Politiewet 2012 regelt de verplichte samenwerking tussen de politie en de buitengewoon opsporingsambtenaren. Ook het Besluit boa (onder meer artikel 29 en 30) bevat afspraken over die samenwerking.", "art. 10 Politiewet 2012; art. 29 Besluit boa", "q10s8l9i"],
["boa", "Je oefent als boa politiebevoegdheden uit. Wiens aanwijzingen volg je daarbij op?", ["Die van de direct toezichthouder.", "Die van de toezichthouder bij het Openbaar Ministerie.", "Die van de burgemeester van de gemeente.", "Die van de vervoerder of je werkgever."], "Bij het uitoefenen van politiebevoegdheden volgt de boa de aanwijzingen op van de direct toezichthouder (de politie) en verstrekt hij hem de gewenste inlichtingen.", "art. 29 Besluit boa", "qe9ocvu"],
// ---------- POLITIE EN GEWELDSINSTRUCTIE ----------
["pol", "Wat verstaan we onder de geweldsinstructie als bedoeld in artikel 90novies Sr?", ["De regels over het gebruik van geweld die op grond van de Politiewet 2012 zijn gesteld.", "Een mondelinge opdracht van een leidinggevende om geweld te gebruiken.", "De regels van de werkgever over het dragen van het uniform en de uitrusting tijdens de dienst.", "Een handleiding van de Politieacademie voor zelfverdediging."], "Artikel 90novies Sr omschrijft de geweldsinstructie: de regels over het aanwenden van geweld die op grond van de Politiewet 2012 zijn gesteld, zoals de Ambtsinstructie. Ook de boa met geweldsbevoegdheid valt daaronder.", "art. 90novies Sr", "qp0ts6y"],
["pol", "Een boa gebruikt geweld en houdt zich daarbij aan de geweldsinstructie. Welke regel uit het Wetboek van Strafrecht beschermt hem?", ["Hij is niet strafbaar (artikel 42 lid 2 Sr).", "Hij is altijd strafbaar, maar krijgt strafvermindering.", "Hij is alleen niet strafbaar als de verdachte geen klacht indient.", "Hij is niet strafbaar als zijn werkgever het geweld goedkeurt."], "Artikel 42 lid 2 Sr bepaalt dat de ambtenaar die bevoegd geweld gebruikt en zich daarbij aan de geweldsinstructie houdt, niet strafbaar is.", "art. 42 lid 2 Sr", "q8nbylq"],
["pol", "Een ambtenaar schendt bij het gebruik van geweld de geweldsinstructie. Waarvoor kan hij worden vervolgd?", ["Voor een speciaal ambtsmisdrijf: het schenden van de geweldsinstructie (artikel 372 Sr).", "Alleen voor een overtreding van zijn arbeidsovereenkomst bij de werkgever.", "Alleen voor huisvredebreuk, omdat hij zijn bevoegdheid te buiten ging.", "Voor niets; een ambtenaar die in functie handelt, kan nooit strafrechtelijk worden vervolgd."], "Artikel 372 Sr stelt het schenden van de geweldsinstructie door een ambtenaar strafbaar als ambtsmisdrijf. Zo hoeft een ambtenaar die bij zijn werk de regels schendt, niet als gewone 'mishandelaar' te worden vervolgd.", "art. 372 Sr", "q1jk7gmu"],
// ---------- MISDRIJVEN TEGEN EN DOOR DE AMBTENAAR ----------
["amb", "Een boa vult in een rapport opzettelijk een onjuiste tijd in, om te verbergen dat hij te laat ter plaatse was. Welk misdrijf kan dit opleveren?", ["Valsheid in geschrift (artikel 225 Sr).", "Smaad (artikel 261 Sr).", "Ambtsdwang (artikel 179 Sr).", "Huisvredebreuk door een ambtenaar (artikel 370 Sr)."], "Wie opzettelijk een geschrift dat bestemd is om tot bewijs te dienen vals opmaakt of vervalst, met het oogmerk het als echt te gebruiken, pleegt valsheid in geschrift. Gebeurt het in een ambtsedig proces-verbaal, dan kan ook meineed aan de orde zijn.", "art. 225 Sr", "q1ib9fhg"],
// ---------- OPSPORINGSAMBTENAAR EN BOA ----------
["boa", "Welke wet is volgens artikel 46 van de Wet politiegegevens ook van toepassing op een boa?", ["De Wet politiegegevens, bij het verwerken van gegevens voor de opsporing.", "De Algemene verordening gegevensbescherming, ook bij de opsporing.", "Geen enkele privacywet, omdat een boa geen politieambtenaar is en geen politiegegevens heeft.", "Alleen de Archiefwet, voor het bewaren van processen-verbaal."], "Artikel 46 Wpg verklaart de Wet politiegegevens (grotendeels) van toepassing op de boa als hij gegevens verwerkt in het kader van de opsporing. Bij toezicht en andere taken geldt de AVG.", "art. 46 Wpg", "q110o7co"],
// ---------- IDENTITEIT, HETERDAAD EN AANHOUDEN ----------
["vrij", "Wat is de Basisregistratie Personen (BRP)?", ["Een landelijke database met persoonsgegevens van de inwoners van Nederland.", "Een register van alle strafbare feiten die een persoon in Nederland ooit heeft gepleegd.", "Een lijst van personen die een identiteitsbewijs hebben aangevraagd.", "Een systeem van de politie met foto's van aangehouden verdachten."], "De BRP bevat persoonsgegevens van inwoners van Nederland (en van Nederlanders in het buitenland). Overheidsorganisaties gebruiken de BRP voor hun taak, bijvoorbeeld om iemands identiteit en adres te controleren.", "Wet BRP", "qqrd7bd"],
// ---------- BEVOEGDHEDEN, TOEZICHT EN JEUGD ----------
["bev", "Op grond van welk artikel kan een toezichthouder inzage van een identiteitsbewijs vorderen?", ["Artikel 5:16a van de Algemene wet bestuursrecht.", "Artikel 27 van het Wetboek van Strafvordering.", "Artikel 447e van het Wetboek van Strafrecht.", "Artikel 12 van de Grondwet."], "Een toezichthouder kan op grond van artikel 5:16a Awb inzage vorderen van een identiteitsbewijs, voor zover dat redelijkerwijs nodig is voor zijn taak. Een opsporingsambtenaar doet dat op grond van artikel 8 Politiewet 2012.", "art. 5:16a Awb; art. 8 Politiewet 2012", "qixw4y6"],
// ---------- IDENTITEIT, HETERDAAD EN AANHOUDEN ----------
["vrij", "Iemand toont bij een controle een identiteitskaart die op naam staat van een ander. Welk strafbaar feit kan dit zijn?", ["Het gebruik van een vals of andermans identiteitsbewijs (artikel 231 lid 2 Sr).", "Het niet voldoen aan de toonplicht voor een identiteitsbewijs (artikel 447e Sr).", "Het opgeven van een valse naam (artikel 435 Sr).", "Valsheid in geschrift door een ambtenaar (artikel 207 Sr)."], "Artikel 231 lid 2 Sr stelt strafbaar wie opzettelijk een vals of vervalst identiteitsbewijs, of een identiteitsbewijs van een ander, gebruikt alsof het zijn eigen is of voorhanden heeft.", "art. 231 lid 2 Sr", "qa6w1d"],
["vrij", "Je ziet geen strafbaar feit gebeuren, maar een getuige wijst je vijf minuten na een vechtpartij de dader aan. Is er nog sprake van ontdekking op heterdaad?", ["Ja, als het feit wordt ontdekt terwijl het wordt begaan of terstond daarna.", "Nee, heterdaad bestaat alleen als je het strafbare feit zelf ziet gebeuren.", "Nee, heterdaad eindigt altijd na precies één minuut.", "Ja, heterdaad duurt tot 24 uur na het strafbare feit."], "Ontdekking op heterdaad is er als het feit wordt ontdekt terwijl het wordt begaan of terstond nadat het is begaan (artikel 128 Sv). Hoeveel tijd mag verlopen, hangt af van de omstandigheden; enkele minuten met een directe aanwijzing kan nog heterdaad zijn.", "art. 128 lid 1 Sv", "qb0ksgq"],
["vrij", "Wanneer spreken we van ontdekking buiten heterdaad?", ["Als het feit pas enige tijd na het plegen wordt ontdekt.", "Als het feit wordt gezien door een burger en niet door een ambtenaar.", "Als het feit wordt gepleegd buiten de bebouwde kom.", "Als de verdachte het feit later zelf bekent."], "Buiten heterdaad is elke ontdekking die niet onder artikel 128 lid 1 Sv valt: het feit wordt pas na enige tijd ontdekt. Aanhouden buiten heterdaad is dan alleen mogelijk bij feiten waarvoor voorlopige hechtenis is toegelaten.", "art. 128 lid 2 Sv; art. 54 Sv", "qiht6qs"],
// ---------- BEVOEGDHEDEN, TOEZICHT EN JEUGD ----------
["bev", "Welke leeftijdsgrens geldt volgens artikel 486 Sv voor strafvervolging?", ["Wie bij het plegen van het feit jonger was dan 12 jaar, wordt niet vervolgd.", "Wie jonger is dan 14 jaar, wordt niet vervolgd.", "Wie jonger is dan 16 jaar, wordt alleen vervolgd als hij een misdrijf heeft gepleegd.", "Er geldt geen leeftijdsgrens; de rechter beslist per geval."], "Personen die bij het begaan van het feit nog geen 12 jaar waren, worden niet vervolgd (artikel 486 Sv). Van 12 tot 18 jaar geldt in beginsel het jeugdstrafrecht (artikel 77a Sr).", "art. 486 Sv; art. 77a Sr", "q1137i2r"],
["bev", "Voor wie geldt in beginsel het jeugdstrafrecht volgens artikel 77a Sr?", ["Voor wie bij het plegen van het feit 12 jaar of ouder was, maar nog geen 18.", "Voor iedereen die op het moment van de zitting bij de rechter nog geen 21 jaar is.", "Alleen voor kinderen die jonger zijn dan 12 jaar.", "Alleen voor jongeren van 16 en 17 jaar die een misdrijf plegen."], "Het jeugdstrafrecht geldt voor wie bij het begaan van het feit 12 maar nog geen 18 jaar was. Bij 16- en 17-jarigen kan de rechter soms het volwassenenstrafrecht toepassen, en tot 23 jaar soms juist het jeugdstrafrecht.", "art. 77a Sr", "q14nnxvn"],
// ---------- PROCES-VERBAAL ----------
["pv", "Wat moet je volgens artikel 27c lid 5 Sv in je proces-verbaal vermelden?", ["Dat je de verdachte de mededelingen over zijn rechten hebt gedaan.", "Welke straf jij passend vindt voor de verdachte.", "Het telefoonnummer en het adres van je werkgever.", "Alleen de verklaring van de verdachte, zonder verdere mededelingen."], "Van de mededelingen die je volgens artikel 27c Sv aan de verdachte doet (zoals over het zwijgrecht en rechtsbijstand), maak je melding in het proces-verbaal. Zo kan de rechter controleren of de rechten zijn gerespecteerd.", "art. 27c lid 5 Sv", "q1y3yyf3"],
// ---------- WET PERSONENVERVOER 2000 ----------
["wp", "Welke verplichting heeft de concessiehouder volgens artikel 30 Wp2000 tegenover reizigers?", ["Reizigers met een geldig vervoerbewijs vervoeren tegen het geldende tarief.", "Elke reiziger een zitplaats geven, ook in de spits en op drukke trajecten.", "Reizigers zonder vervoerbewijs altijd gratis laten meereizen.", "Alleen reizigers vervoeren die een abonnement hebben."], "De concessiehouder is verplicht reizigers die beschikken over een geldig vervoerbewijs binnen het concessiegebied te vervoeren tegen het geldende tarief, en hij moet nationale vervoerbewijzen accepteren.", "art. 30 Wp2000", "q20jt0c"],
["wp", "Wat regelt artikel 74 Wp2000?", ["Dat bij algemene maatregel van bestuur nadere regels worden gesteld, zoals in het Besluit personenvervoer 2000.", "Dat boa's in het openbaar vervoer een vuurwapen mogen dragen bij hun dienst.", "Dat de vervoerder zelf boetes mag vaststellen voor elk gedrag dat hij in zijn voertuigen ongewenst vindt, zonder dat de wet dat regelt.", "Dat de gemeente een vergunning moet geven voor elke bushalte binnen haar grondgebied."], "Artikel 74 Wp2000 bepaalt dat bij algemene maatregel van bestuur nadere regels worden gesteld over orde, rust en veiligheid, de manier waarop aanwijzingen worden gegeven, het gebruik van vervoerbewijzen en de betaling. Dat is uitgewerkt in het Besluit personenvervoer 2000.", "art. 74 Wp2000", "qd5uepf"],
["wp", "Wat regelt artikel 89 Wp2000 voor boa's in het openbaar vervoer?", ["Dat zij ook bepaalde feiten uit het Wetboek van Strafrecht kunnen opsporen.", "Dat zij alleen toezicht houden en nooit iets mogen opsporen.", "Dat zij in het hele land politiebevoegdheden hebben, ook buiten het openbaar vervoer.", "Dat zij een verdachte maximaal zes uur mogen ophouden voor onderzoek."], "Artikel 89 Wp2000 regelt de opsporing: door de ministers aangewezen personen zijn belast met de opsporing van overtredingen van de Wp2000, en hun opsporingsbevoegdheid kan worden uitgebreid tot feiten uit het Wetboek van Strafrecht.", "art. 89 Wp2000", "qum2yus"],
// ---------- BESLUIT PERSONENVERVOER 2000 ----------
["bp", "Een reiziger met een visuele beperking reist met zijn geleidehond in de bus. Moet hij voor de hond betalen?", ["Nee, voor een hond die een gehandicapte begeleidt, is geen vervoerprijs verschuldigd.", "Ja, voor elke hond geldt het tarief van een kind, ook voor een hond die een gehandicapte begeleidt.", "Ja, maar alleen in de spits en niet daarbuiten.", "Alleen als de hond groter is dan handbagage."], "Volgens artikel 46 Bp2000 is geen vervoerprijs verschuldigd voor handbagage en voor een hond die een gehandicapte begeleidt. Voor fietsen en andere levende dieren kan wel een vervoerprijs gelden.", "art. 46 Bp2000", "q1komnu2"],
["bp", "Een reiziger heeft een opeisbare schuld bij de vervoerder voor eerdere vervoerbewijzen. Wat is het gevolg volgens artikel 49 Bp2000?", ["Hij heeft geen recht op een vervoerbewijs op naam zolang de schuld niet is voldaan.", "Hij mag nooit meer met het openbaar vervoer reizen, ook niet met een los kaartje.", "De vervoerder mag zijn identiteitsbewijs innemen tot hij betaalt.", "Hij moet de schuld binnen 24 uur betalen bij een boa."], "Zolang een opeisbare schuld ter zake van vervoerbewijzen niet is voldaan, heeft de reiziger geen recht op een op naam gesteld vervoerbewijs (artikel 49 Bp2000).", "art. 49 Bp2000", "qvikgzz"],
// ---------- TOEZICHT IN HET OV ----------
["ovt", "Wat verstaan we volgens artikel 1:1 Awb onder een bestuursorgaan?", ["Een orgaan van een rechtspersoon met openbaar gezag, of een persoon of college met openbaar gezag bekleed.", "Iedere organisatie die diensten verleent aan burgers, ook een gewoon bedrijf zonder enige overheidstaak of openbaar gezag.", "Alleen de ministers en de staatssecretarissen in de regering.", "Alleen de gemeenteraad en de Provinciale Staten."], "Een bestuursorgaan is een orgaan van een rechtspersoon die krachtens publiekrecht is ingesteld (zoals een gemeente), of een andere persoon of college met enig openbaar gezag bekleed (artikel 1:1 lid 1 Awb).", "art. 1:1 Awb", "qwqst05"],
// ---------- BEVOEGDHEDEN, TOEZICHT EN JEUGD ----------
["bev", "Wat verstaan we volgens artikel 5:11 Awb onder een toezichthouder?", ["Een persoon die bij of krachtens wettelijk voorschrift is belast met toezicht op de naleving.", "Iedere ambtenaar die bij een gemeente of provincie in dienst is.", "Een persoon die strafbare feiten opspoort onder het gezag van de officier van justitie en daarvoor een akte heeft.", "Een beveiliger die door een bedrijf is ingehuurd om te surveilleren."], "Een toezichthouder is een persoon die bij of krachtens wettelijk voorschrift is belast met het houden van toezicht op de naleving van het bepaalde bij of krachtens een wettelijk voorschrift (artikel 5:11 Awb).", "art. 5:11 Awb", "qpw1wsm"],
["bev", "Welke plaatsen mag een toezichthouder op grond van artikel 5:15 Awb zonder toestemming betreden?", ["Alle plaatsen, met uitzondering van een woning zonder toestemming van de bewoner.", "Alle plaatsen, ook woningen, zolang hij zijn legitimatiebewijs toont aan de bewoner.", "Alleen openbare plaatsen, zoals straten en parken.", "Geen enkele plaats zonder schriftelijke toestemming van de eigenaar."], "Een toezichthouder mag met de benodigde apparatuur elke plaats betreden, met uitzondering van een woning zonder toestemming van de bewoner. Zo nodig verschaft hij zich toegang met behulp van de sterke arm.", "art. 5:15 Awb", "q1xv0or6"],
// ---------- MISDRIJVEN TEGEN EN DOOR DE AMBTENAAR ----------
["amb", "Een reiziger verzet zich met geweld tegen zijn rechtmatige aanhouding, waarbij de boa een gebroken pols oploopt. Welk artikel verhoogt het strafmaximum?", ["Artikel 181 Sr: wederspannigheid met lichamelijk letsel tot gevolg.", "Artikel 185 Sr: opschudding bij een ambtenaar in functie.", "Artikel 266 Sr: eenvoudige belediging.", "Artikel 447e Sr: het niet tonen van een identiteitsbewijs op vordering."], "Artikel 181 Sr verhoogt de straf voor ambtsdwang en wederspannigheid als die enig lichamelijk letsel, zwaar lichamelijk letsel of de dood tot gevolg hebben.", "art. 181 Sr", "q9orq43"],
["amb", "Twee vrienden verzetten zich samen met geweld tegen de rechtmatige aanhouding van een van hen. Welk artikel is specifiek op deze situatie van toepassing?", ["Artikel 182 Sr: wederspannigheid met verenigde krachten door twee of meer personen.", "Artikel 141 Sr: openlijke geweldpleging tegen personen of goederen op de openbare weg.", "Artikel 180 Sr, maar alleen voor degene die werd aangehouden.", "Artikel 300 Sr: eenvoudige mishandeling."], "Artikel 182 Sr verzwaart de straf als ambtsdwang of wederspannigheid door twee of meer personen met verenigde krachten wordt gepleegd, zeker als daarbij letsel ontstaat.", "art. 182 Sr", "q1qn5dpo"],
["amb", "Wat verstaan we onder dwang als bedoeld in artikel 284 Sr?", ["Iemand door geweld of bedreiging wederrechtelijk dwingen iets te doen, niet te doen of te dulden.", "Een verdachte met toestemming van de officier van justitie verplichten een verklaring af te leggen.", "Iemand vriendelijk maar dringend vragen om mee te werken aan een controle.", "Een ambtenaar die een burger verplicht een vervoerbewijs te tonen."], "Dwang (artikel 284 Sr) is iemand wederrechtelijk dwingen iets te doen, niet te doen of te dulden, door geweld, een andere feitelijkheid of bedreiging daarmee. Zo is ook de boa beschermd tegen druk om iets wel of niet te doen.", "art. 284 Sr", "qrs8iha"],
["amb", "Iemand bedreigt je als boa tijdens je werk met de dood. Wat is het gevolg voor de straf?", ["Het strafmaximum voor bedreiging wordt met een derde verhoogd, omdat je ambtenaar in functie bent.", "Er is geen gevolg, want bedreiging van een ambtenaar is een klachtdelict waarvoor de ambtenaar zelf klacht moet indienen.", "De bedreiging is alleen strafbaar als die schriftelijk is gedaan.", "De bedreiger krijgt alleen een bestuurlijke boete van de werkgever."], "Bedreiging met onder meer een levensdelict of zware mishandeling is strafbaar (artikel 285 lid 1 Sr). Is de bedreiging gericht tegen een ambtenaar tijdens of vanwege zijn werk, dan wordt het strafmaximum met een derde verhoogd (artikel 285 lid 5 Sr).", "art. 285 lid 1 en 5 Sr", "qcnmp8x"],
["amb", "Iemand probeert je als boa een klap te geven, maar mist. Is hij strafbaar voor poging tot eenvoudige mishandeling?", ["Nee, poging tot eenvoudige mishandeling is niet strafbaar.", "Ja, elke poging tot een misdrijf is strafbaar.", "Ja, maar alleen als je aangifte doet.", "Ja, want bij een ambtenaar in functie is iedere poging tot mishandeling strafbaar."], "Poging tot eenvoudige mishandeling is niet strafbaar (artikel 300 lid 5 Sr). De dader kan wel strafbaar zijn voor bijvoorbeeld bedreiging of wederspannigheid, afhankelijk van de situatie.", "art. 300 lid 5 Sr", "qo8duy0"],
["amb", "Een reiziger mishandelt een boa OV tijdens diens werk. Wat is het gevolg voor het strafmaximum?", ["De gevangenisstraf kan met een derde worden verhoogd.", "De straf wordt gehalveerd, omdat een boa geen politieambtenaar is.", "Er geldt dezelfde straf als bij een gewone burger, zonder verhoging.", "Alleen een geldboete is mogelijk, geen gevangenisstraf."], "Bij mishandeling van een ambtenaar tijdens of vanwege de rechtmatige uitoefening van zijn bediening kan de gevangenisstraf met een derde worden verhoogd (artikel 304 Sr).", "art. 300 en 304 Sr", "q1pliwaa"],
// ---------- GEMEENTE, SAMENWERKING EN KETENPARTNERS (DOMEIN I) ----------
["gem", "Wie is voorzitter van het bestuur van de veiligheidsregio?", ["Een burgemeester uit de regio, aangewezen door de Kroon.", "De commissaris van de Koning van de provincie.", "De commandant van de brandweer in de regio.", "De hoofdofficier van justitie van het arrondissement waarin de regio ligt."], "Het bestuur van de veiligheidsregio bestaat uit de burgemeesters van de gemeenten in de regio. Een van hen wordt bij koninklijk besluit als voorzitter benoemd, meestal de burgemeester van de grootste gemeente.", "Wet veiligheidsregio's", "q1vp5tta"],
["gem", "Wie is volgens artikel 172 van de Gemeentewet belast met de handhaving van de openbare orde in de gemeente?", ["De burgemeester.", "De gemeenteraad.", "Het college van burgemeester en wethouders.", "De officier van justitie."], "De burgemeester is belast met de handhaving van de openbare orde (artikel 172 Gemeentewet). Hij heeft daarvoor ook het gezag over de politie bij de handhaving van de openbare orde.", "art. 172 Gemeentewet", "q8uuzup"],
["gem", "Wanneer kan de burgemeester een noodverordening vaststellen?", ["Bij oproerige beweging of ernstige vrees voor zware wanorde of rampen.", "Elke keer dat de gemeenteraad niet op tijd vergadert over een nieuwe regel.", "Als er in een straat vaker dan drie keer per maand wordt geparkeerd.", "Alleen na toestemming van de minister van Binnenlandse Zaken."], "Bij oproerige beweging, andere ernstige wanordelijkheden of rampen, of ernstige vrees daarvoor, kan de burgemeester algemeen verbindende voorschriften geven die nodig zijn voor de openbare orde. De noodverordening moet door de raad worden bekrachtigd.", "art. 176 Gemeentewet", "q1btoukh"],
["gem", "Door welk orgaan wordt een provinciale verordening vastgesteld?", ["Door Provinciale Staten.", "Door Gedeputeerde Staten.", "Door de commissaris van de Koning.", "Door de minister van Binnenlandse Zaken."], "Provinciale Staten maken de provinciale verordeningen (artikel 143 Provinciewet), zoals de gemeenteraad de gemeentelijke verordeningen vaststelt.", "art. 143 Provinciewet; art. 127 Gw", "q21qc6o"],
["gem", "Wanneer treedt volgens het inzetcriterium in de regel de politie op in plaats van de boa in de openbare ruimte?", ["Als er een gevaarlijke of gewelddadige situatie te verwachten is.", "Als het strafbare feit tijdens de surveillance direct en eenvoudig te zien is.", "Als het feit met een gecodeerde bon kan worden afgedaan.", "Als het gaat om een overtreding van de APV."], "Volgens het inzetcriterium uit de Beleidsregels boa handelt de boa leefbaarheidsfeiten af die direct te constateren, eenvoudig bewijsbaar en feitgecodeerd af te doen zijn. Bij geweld, veelplegers, aanzienlijke schade of een te verwachten gevaarlijke setting is de politie aan zet.", "Beleidsregels boa, paragraaf 6", "qknfa90"],
["gem", "Welke organisatie brengt informatie van gemeenten, politie, OM en Belastingdienst samen om ondermijnende criminaliteit aan te pakken?", ["Het Regionaal Informatie- en Expertise Centrum (RIEC).", "De Nederlandse Voedsel- en Warenautoriteit (NVWA), samen met de GGD.", "De Nederlandse Arbeidsinspectie.", "De veiligheidsregio."], "Het RIEC ondersteunt partners zoals gemeenten, politie, het Openbaar Ministerie en de Belastingdienst bij de integrale aanpak van ondermijnende criminaliteit.", "Toetsmatrijs Domein I, toetsterm 1.3.2", "q1ws35b3"],
["gem", "Je ziet bij een controle dat een snackbar vlees opslaat bij een te hoge temperatuur. Welke ketenpartner is hiervoor de toezichthouder?", ["De Nederlandse Voedsel- en Warenautoriteit (NVWA).", "De Nederlandse Arbeidsinspectie, die ook toeziet op voedselveiligheid.", "De brandweer.", "De wegbeheerder."], "De NVWA houdt toezicht op de veiligheid van voedsel en producten. De Arbeidsinspectie gaat over arbeidsomstandigheden en eerlijk werk; de brandweer over brandveiligheid en hulpverlening.", "Toetsmatrijs Domein I, toetsterm 1.3.2", "qutm7cf"],
// ---------- BEVOEGDHEDEN, TOEZICHT EN JEUGD ----------
["bev", "Met welk doel verzamelt een boa binnen het strafrecht gegevens van een persoon?", ["Om de identiteit vast te stellen, vergunningen te controleren en een dossier op te bouwen.", "Om een persoonlijk profiel op te bouwen dat aan commerciële partijen kan worden verkocht.", "Om de gegevens door te geven aan de buren van de verdachte.", "Om zelf te bepalen welke straf de persoon verdient."], "Een boa verzamelt gegevens om de identiteit vast te stellen, vergunningen en ontheffingen te controleren en voor dossiervorming, zoals voortgangscontrole bij steeds terugkerende overtredingen.", "Toetsmatrijs Domein I, toetsterm 2.1.3", "q14d9hjh"],
["bev", "Wat verstaan we onder herhaalde toepassing van eenzelfde bevoegdheid?", ["Dezelfde bevoegdheid opnieuw gebruiken in dezelfde zaak, bijvoorbeeld een tweede keer staande houden.", "Een bevoegdheid gebruiken die je eerder in een andere zaak al hebt gebruikt.", "Na het staande houden doorgaan met aanhouden en daarna ophouden voor onderzoek van de verdachte.", "Een bevoegdheid uitvoeren samen met een collega."], "Herhaalde toepassing is het opnieuw toepassen van dezelfde bevoegdheid binnen een zaak, zoals een verdachte die al staande was gehouden nog eens staande houden. Dat moet wel nodig en proportioneel zijn.", "Toetsmatrijs Domein I, toetsterm 2.2.3", "q1j1q6fk"],
["bev", "Wat verstaan we onder voortgezette toepassing van bevoegdheden?", ["Na de ene bevoegdheid een volgende inzetten, zoals na het staande houden aanhouden.", "Dezelfde bevoegdheid elke dag opnieuw gebruiken bij dezelfde persoon, ook zonder nieuwe aanleiding.", "Een bevoegdheid langer gebruiken dan de wet toestaat.", "Een bevoegdheid laten overnemen door een toezichthouder."], "Bij voortgezette toepassing volgt op de ene bevoegdheid een volgende, zwaardere of andere bevoegdheid, bijvoorbeeld staande houden, daarna aanhouden en daarna ophouden voor onderzoek. Voor elke stap moet je bevoegd zijn.", "Toetsmatrijs Domein I, toetsterm 2.2.3", "q12z4zto"],
["bev", "Hoe vaak kan een jongere een Halt-afdoening aangeboden krijgen?", ["Ten hoogste twee keer.", "Eén keer in zijn leven.", "Zo vaak als nodig, zolang hij jonger is dan 18 jaar.", "Ten hoogste drie keer per jaar."], "Een Halt-afdoening kan ten hoogste twee keer worden aangeboden. Halt is bedoeld voor lichte feiten die in het Besluit aanwijzing Halt-feiten staan, zoals vernieling of winkeldiefstal met een lage waarde.", "art. 77e Sr; Besluit aanwijzing Halt-feiten 2024", "qr2f6qu"],
// ---------- VERDACHTE ----------
["vd", "Je verhoort een minderjarige verdachte. Welk aanvullend recht heeft hij volgens artikel 488ab Sv?", ["Het recht om bij het verhoor te worden vergezeld door een ouder, voogd of vertrouwenspersoon.", "Het recht om het verhoor zonder opgaaf van redenen een week uit te stellen.", "Het recht om zelf te bepalen welke boa hem verhoort.", "Het recht om geen identiteitsbewijs te hoeven tonen."], "Een minderjarige verdachte heeft het recht om bij het verhoor te worden vergezeld door zijn ouders of voogd, of een andere vertrouwenspersoon (artikel 488ab Sv), tenzij dat het onderzoek schaadt.", "art. 488ab Sv", "qw3bzpp"],
// ---------- BESTUURSRECHT (DOMEIN I) ----------
["bst", "Welke twee functies heeft het bestuursrecht?", ["Een waarborgfunctie tegen de overheid en een instrumentele functie om te besturen.", "Een straffunctie voor misdrijven en een afschrikfunctie voor alle overtredingen.", "Een functie voor geschillen tussen burgers en een functie voor arbeidsrecht.", "Een opsporingsfunctie en een vervolgingsfunctie."], "Het bestuursrecht beschermt burgers en bedrijven tegen het handelen van de overheid (waarborgfunctie) en geeft de overheid instrumenten om de samenleving te besturen, zoals vergunningen en sancties (instrumentele functie).", "Toetsmatrijs Domein I, toetsterm 3.1.1", "qs7nfea"],
["bst", "Wat beschrijft de Algemene wet bestuursrecht (Awb)?", ["Algemene regels voor de verhouding tussen de overheid en burgers en bedrijven.", "De strafbare feiten die een boa in de openbare ruimte mag opsporen en afdoen.", "De regels voor de samenwerking tussen politie en Openbaar Ministerie.", "De verkeersregels voor weggebruikers op de openbare weg."], "De Awb bevat algemene regels voor de verhouding tussen de overheid enerzijds en burgers en bedrijven anderzijds, zoals over besluiten, bezwaar, toezicht en bestuurlijke sancties.", "Toetsmatrijs Domein I, toetsterm 3.1.2", "qlz52ax"],
["bst", "Je verhoort als toezichthouder een overtreder met het oog op een bestuurlijke boete. Wat moet je volgens artikel 5:10a Awb vooraf zeggen?", ["Dat hij niet verplicht is om op vragen te antwoorden.", "Dat hij verplicht is om volledig mee te werken aan het verhoor.", "Dat hij recht heeft op een gratis advocaat van de gemeente.", "Dat de boete lager wordt als hij meteen bekent."], "Wie wordt verhoord met het oog op een bestraffende sanctie, zoals een bestuurlijke boete, hoeft niet mee te werken aan zijn eigen veroordeling. Daarom deel je vooraf mee dat hij niet verplicht is te antwoorden: de cautie in het bestuursrecht.", "art. 5:10a Awb", "q9im04i"],
["bst", "Wat verstaan we volgens artikel 5:2 Awb onder een bestuurlijke sanctie?", ["Een verplichting of onthouding van een aanspraak die een bestuursorgaan oplegt wegens een overtreding.", "Een straf die alleen de strafrechter kan opleggen na een strafzaak tegen de verdachte.", "Een waarschuwing van een boa zonder verdere gevolgen.", "Een boete die een burger aan de gemeente kan opleggen."], "Een bestuurlijke sanctie is een door een bestuursorgaan wegens een overtreding opgelegde verplichting of onthouding van een aanspraak. Je onderscheidt herstelsancties (zoals bestuursdwang en dwangsom) en bestraffende sancties (zoals de bestuurlijke boete).", "art. 5:2 Awb", "q1m1yew5"],
["bst", "Wat is een bestuurlijke boete volgens artikel 5:40 Awb?", ["Een bestraffende sanctie: de verplichting om een geldsom te betalen.", "Een herstelsanctie die de overtreding ongedaan maakt.", "Een vergoeding die de gemeente aan de burger betaalt.", "Een geldsom die pas verschuldigd is als een last niet wordt uitgevoerd."], "De bestuurlijke boete is een bestraffende sanctie, bestaande uit de onvoorwaardelijke verplichting een geldsom te betalen (artikel 5:40 Awb). Een geldsom die pas verschuldigd is als een last niet wordt uitgevoerd, is een dwangsom.", "art. 5:40 Awb", "qh7hnib"],
["bst", "Een bedrijf laat illegaal afval op een stoep staan. De gemeente laat het op kosten van het bedrijf weghalen. Welke sanctie is dit?", ["Een last onder bestuursdwang.", "Een last onder dwangsom.", "Een bestuurlijke boete (bestraffende sanctie).", "Een strafbeschikking."], "Bij een last onder bestuursdwang treedt het bestuursorgaan zelf feitelijk op om de overtreding te beëindigen, op kosten van de overtreder (artikel 5:21 Awb).", "art. 5:21 Awb", "qe024l6"],
["bst", "Wat houdt een last onder dwangsom in?", ["De overtreder moet de overtreding herstellen, anders verbeurt hij een geldsom.", "De gemeente haalt zelf de overtreding weg en stuurt de rekening.", "De overtreder krijgt direct een boete, ook als hij de overtreding meteen herstelt.", "De overtreder moet een cursus volgen bij de gemeente."], "Bij een last onder dwangsom krijgt de overtreder een herstellende last opgelegd. Voert hij die niet (op tijd) uit, dan verbeurt hij een geldsom (artikel 5:31d Awb). Het is een herstelsanctie, geen straf.", "art. 5:31d Awb", "q1hiioof"],
["bst", "Een ondernemer overtreedt twee verschillende voorschriften. Hoeveel bestuurlijke sancties kunnen worden opgelegd volgens artikel 5:8 Awb?", ["Voor elk overtreden voorschrift afzonderlijk een sanctie.", "Altijd maar één sanctie, voor de zwaarste overtreding.", "Geen; bij twee overtredingen moet de rechter beslissen.", "Alleen een waarschuwing voor de tweede overtreding, en een sanctie voor de eerste."], "Overtreedt iemand meer voorschriften, dan kan voor elk van die overtredingen afzonderlijk een bestuurlijke sanctie worden opgelegd (artikel 5:8 Awb).", "art. 5:8 Awb", "q1nx6835"],
["bst", "Aan wie komt een ingevorderde dwangsom of bestuurlijke boete in beginsel toe?", ["Aan het bestuursorgaan dat de sanctie heeft opgelegd.", "Aan de Staat, via het Centraal Justitieel Incassobureau.", "Aan de boa die de overtreding heeft vastgesteld.", "Aan de buurtbewoners die overlast hadden."], "De ingevorderde som komt in beginsel toe aan het bestuursorgaan dat de sanctie heeft opgelegd (artikel 5:10 lid 1 Awb), bijvoorbeeld de gemeente.", "art. 5:10 Awb", "q1yq3izz"],
["bst", "Mag een bestuursorgaan bij het uitvoeren van bestuursdwang een woning binnengaan zonder toestemming van de bewoner?", ["Ja, als dat nodig is voor de bestuursdwang, met inachtneming van de regels over binnentreden.", "Nee, nooit; bestuursdwang houdt altijd op bij de voordeur van een woning.", "Ja, altijd en zonder enige formaliteit.", "Alleen als de politie de woning eerst heeft doorzocht."], "Artikel 5:27 Awb geeft de personen die met de uitvoering van bestuursdwang zijn belast de bevoegdheid elke plaats te betreden, ook een woning zonder toestemming van de bewoner, voor zover dat redelijkerwijs nodig is. Voor de woning gelden de regels van de Algemene wet op het binnentreden.", "art. 5:27 Awb", "qexpqbt"],
["bst", "Wat mag een bestuursorgaan bij bestuursdwang doen met zaken die het weghaalt, zoals een weesfiets?", ["Meevoeren en opslaan, en de eigenaar daarvan op de hoogte brengen.", "Direct vernietigen zonder iemand te informeren, omdat het afval is.", "Verkopen en de opbrengst aan de boa geven.", "Teruggeven aan de eerste persoon die erom vraagt."], "Bij bestuursdwang mogen zaken worden meegevoerd en opgeslagen (artikel 5:29 Awb). De eigenaar krijgt zo mogelijk een proces-verbaal of bericht; onder voorwaarden kan de zaak later worden verkocht of vernietigd.", "art. 5:29 Awb", "q1ldki7q"],
// ---------- APV (DOMEIN I) ----------
["apv", "Wat verstaan we volgens de APV onder een openbare plaats?", ["Een plaats die krachtens bestemming of vast gebruik openstaat voor het publiek, zoals een plein of park.", "Alleen een gebouw van de gemeente dat voor publiek openstaat, zoals het stadhuis, de bibliotheek of het zwembad.", "Elke plaats waar meer dan tien mensen tegelijk aanwezig zijn.", "Alleen de openbare weg, zonder parken of pleinen."], "De APV verwijst voor 'openbare plaats' naar de Wet openbare manifestaties: een plaats die krachtens bestemming of vast gebruik openstaat voor het publiek, zoals straten, pleinen en parken.", "art. 1:1 Model-APV", "q6vxejj"],
["apv", "Wat verstaan we in de APV onder 'weg'?", ["Alle wegen in de zin van de Wegenverkeerswet 1994, inclusief voetpaden, fietspaden en bermen.", "Alleen de rijbaan waarop auto's rijden, zonder trottoirs, fietspaden of bermen ernaast.", "Alleen wegen die door de provincie worden beheerd.", "Alleen doorgaande wegen buiten de bebouwde kom."], "De APV verwijst voor 'weg' naar de Wegenverkeerswet 1994: alle voor het openbaar verkeer openstaande wegen of paden, met de daarin liggende bruggen en duikers en de bermen en zijkanten.", "art. 1:1 Model-APV; art. 1 WVW 1994", "qhwp7r4"],
["apv", "Een groep jongeren veroorzaakt op een plein wanorde en weigert weg te gaan na een bevel van de politie. Welke APV-bepaling sluit hierop aan?", ["Het verbod op samenscholing en ordeverstoring (artikel 2:1 APV).", "Het verbod op hinderlijk drankgebruik (artikel 2:48 APV).", "Het verbod op het doen van je natuurlijke behoefte (artikel 4:8 APV).", "Het verbod om zonder vergunning te collecteren (artikel 5:13 APV)."], "Artikel 2:1 APV verbiedt op een openbare plaats deel te nemen aan een samenscholing, wanordelijkheden te veroorzaken of daartoe aan te zetten, en geeft de politie de bevoegdheid om aanwezigen een bevel te geven zich te verwijderen.", "art. 2:1 Model-APV", "q1gc4q8y"],
["apv", "Iemand plakt zonder toestemming van de eigenaar posters op de gevel van een winkel. Wat overtreedt hij in de APV?", ["Het verbod om zonder schriftelijke toestemming van de eigenaar aan te plakken (plakken en kladden).", "Niets, zolang de posters geen handelsreclame bevatten en na een week worden weggehaald.", "Het verbod op hinderlijk gedrag in openbare gebouwen.", "Het verbod op het innemen van een standplaats zonder vergunning."], "De APV verbiedt zonder schriftelijke toestemming van de eigenaar of beheerder iets aan te plakken of te bekladden dat vanaf een openbare plaats zichtbaar is (artikel 2:42 Model-APV, plakken en kladden). De gemeente wijst plakzuilen aan voor vrij aanplakken.", "art. 2:42 Model-APV", "qd610zs"],
["apv", "Een volwassene drinkt bier op een bankje in een gebied dat het college heeft aangewezen als gebied waar alcohol drinken verboden is. Wat overtreedt hij?", ["Het verbod op hinderlijk drankgebruik (artikel 2:48 APV).", "Artikel 45 van de Alcoholwet.", "Niets; het verbod op alcohol drinken op straat geldt alleen voor minderjarigen.", "Het verbod op samenscholing (artikel 2:1 APV)."], "Artikel 2:48 APV verbiedt in een door het college aangewezen gebied op een openbare plaats alcohol te drinken of aangebroken flessen of blikjes bij je te hebben. Voor minderjarigen geldt daarnaast het algemene verbod van artikel 45 Alcoholwet.", "art. 2:48 Model-APV", "q1jyprqi"],
["apv", "Je ziet iemand op straat drugs gebruiken. Welke APV-bepaling kan hierop van toepassing zijn?", ["Het verbod op openlijk drugsgebruik op straat (artikel 2:74a APV).", "Het verbod op aanplakken zonder toestemming (artikel 2:42 APV).", "Het verbod op geluidhinder (artikel 4:6 APV).", "Het verbod op het parkeren van grote voertuigen in woonwijken (artikel 5:8 APV)."], "Artikel 2:74a APV verbiedt het gebruik van drugs uit de Opiumwet op de weg, een openbare plaats of in een voor publiek toegankelijk gebouw. Artikel 2:74 APV gaat over rondhangen met het doel drugs te verhandelen.", "art. 2:74a Model-APV", "qvea9za"],
["apv", "Een bewoner speelt in zijn tuin urenlang keiharde muziek, waardoor de buren veel overlast hebben. Welke APV-bepaling sluit hierop aan?", ["Het verbod op geluidhinder voor omwonenden (artikel 4:6 APV).", "Het verbod op samenscholing (artikel 2:1 APV).", "Het verbod op hinderlijk gedrag in een openbaar gebouw of op een openbare plaats.", "Het verbod op vuur stoken (artikel 5:34 APV)."], "Artikel 4:6 APV verbiedt het in werking hebben van toestellen of geluidsapparaten die geluidhinder voor omwonenden of andere gebruikers van de weg veroorzaken.", "art. 4:6 Model-APV", "qn4tukv"],
["apv", "Een eigenaar laat zijn hond binnen de bebouwde kom op straat loslopen. Wat geldt volgens de APV in de regel?", ["Dat is verboden: binnen de bebouwde kom moet een hond aangelijnd zijn, behalve op aangewezen losloopplaatsen.", "Dat mag altijd, zolang de hond geen andere mensen of honden aanvalt, lastigvalt of schade aanricht aan eigendommen van anderen.", "Dat mag alleen overdag, tussen zonsopgang en zonsondergang, en niet 's avonds.", "Dat is alleen verboden voor honden die groter zijn dan een middelgrote hond."], "Volgens de APV mag de eigenaar of houder een hond binnen de bebouwde kom op de weg niet los laten lopen, behalve op plaatsen die het college als losloopgebied heeft aangewezen.", "art. 2:57 Model-APV", "qojyhkm"],
["apv", "Een hondenbezitter laat de poep van zijn hond op de stoep liggen. Wat overtreedt hij volgens de APV?", ["De opruimplicht; hij moet de uitwerpselen direct verwijderen en een opruimmiddel bij zich hebben.", "Niets, zolang de hond en zijn eigenaar buiten de bebouwde kom wonen en alleen op doorreis zijn.", "Het verbod op geluidhinder voor omwonenden.", "Het verbod op het innemen van een standplaats."], "De APV verplicht de eigenaar of houder de uitwerpselen van zijn hond op de weg of in een park direct op te ruimen. Hij moet ook een geschikt opruimmiddel bij zich hebben en dat op verzoek tonen aan een toezichthouder.", "art. 2:58 Model-APV", "qrcviop"],
["apv", "Iemand gaat zonder vergunning langs de deuren om geld in te zamelen voor een goed doel. Wat overtreedt hij?", ["Het verbod om zonder vergunning geld of goederen in te zamelen (collecteren).", "Het verbod op venten met gedrukte stukken.", "Niets, want collecteren voor een erkend goed doel is altijd vrij en zonder vergunning toegestaan.", "Het verbod op het innemen van een standplaats."], "De APV verbiedt zonder vergunning van het college geld of goederen in te zamelen (artikel 5:13 Model-APV). Gemeenten werken vaak met een collecterooster voor erkende goede doelen.", "art. 5:13 Model-APV", "qyryrir"],
["apv", "Een ondernemer verkoopt zonder vergunning oliebollen vanuit een kraam op een vaste plek op straat. Wat overtreedt hij?", ["Het verbod om zonder vergunning een standplaats in te nemen.", "Het verbod op venten met gedrukte stukken.", "Het verbod op hinderlijk drankgebruik.", "Niets, zolang hij alleen eten verkoopt en geen alcohol of tabak."], "Voor het innemen of hebben van een standplaats, een vaste plek op een openbare plaats om goederen te verkopen of diensten aan te bieden, is een vergunning van het college nodig (artikel 5:18 Model-APV).", "art. 5:17 en 5:18 Model-APV", "q1lxcdvr"],
["apv", "Een straatmuzikant treedt op op een plaats die de burgemeester voor straatartiesten verboden heeft verklaard. Wat geldt?", ["Hij overtreedt de APV, want op aangewezen plaatsen is optreden verboden.", "Hij overtreedt niets, want muziek maken valt onder de vrijheid van meningsuiting.", "Hij overtreedt alleen iets als hij geld vraagt aan voorbijgangers.", "Hij moet alleen stoppen als een omwonende een klacht indient."], "De APV verbiedt op door de burgemeester aangewezen plaatsen op te treden als straatartiest, bijvoorbeeld in het belang van de openbare orde. De burgemeester kan daarbij dagen en tijden bepalen en ontheffing verlenen.", "art. 2:9 Model-APV", "q1asmnpt"],
["apv", "Iemand plast na het uitgaan tegen een gevel in het centrum. Wat overtreedt hij?", ["Het verbod om op of aan de weg je natuurlijke behoefte te doen buiten een toilet (wildplassen).", "Het verbod op samenscholing en ordeverstoring.", "Het verbod op hinderlijk drankgebruik in een aangewezen gebied.", "Niets, zolang er geen openbaar toilet in de directe omgeving te vinden is."], "De APV verbiedt op of aan de weg, op een openbare plaats of in een openbaar gebouw je natuurlijke behoefte te doen buiten een toilet of urinoir (artikel 4:8 Model-APV).", "art. 4:8 Model-APV", "qhf76f0"],
["apv", "Een auto met een kapotte motor staat al een week op de openbare weg geparkeerd. Wat geldt volgens de APV?", ["Een defect voertuig mag niet langer dan drie dagen op de weg geparkeerd staan.", "Een defect voertuig mag onbeperkt blijven staan, zolang het een kenteken heeft.", "Een defect voertuig moet binnen 24 uur worden weggehaald.", "Alleen de politie mag hier iets aan doen, de APV regelt het niet."], "De APV verbiedt een voertuig dat niet kan rijden langer dan drie dagen op de weg te parkeren (artikel 5:5 Model-APV). Daarna kan de gemeente handhaven, bijvoorbeeld met bestuursdwang.", "art. 5:5 Model-APV", "q1kegnrn"],
["apv", "Een caravan staat vijf dagen achter elkaar op de openbare weg in een woonwijk. Wat geldt volgens de APV?", ["Een kampeermiddel mag niet langer dan drie achtereenvolgende dagen op de weg staan.", "Een caravan mag altijd op de weg staan, zolang hij goed is afgesloten en een geldig kenteken heeft.", "Een caravan mag maximaal tien dagen per jaar op de weg staan.", "De APV regelt niets over caravans; alleen het RVV is van toepassing."], "De APV verbiedt een kampeermiddel, zoals een caravan of camper, langer dan drie achtereenvolgende dagen op de weg te plaatsen (artikel 5:6 Model-APV).", "art. 5:6 Model-APV", "qtku2u8"],
["apv", "Welk voertuig valt in de APV onder het parkeerverbod voor grote voertuigen?", ["Een voertuig dat met lading langer is dan 6 meter of hoger dan 2,40 meter.", "Elk voertuig dat zwaarder is dan 1.000 kilogram, zoals een grote stationwagen.", "Elk voertuig met meer dan vier wielen, ook een personenauto met aanhanger.", "Alleen bussen van het openbaar vervoer die buiten hun dienstregeling stilstaan."], "De APV verbiedt een voertuig dat, inclusief de lading, langer is dan 6 meter of hoger dan 2,40 meter te parkeren op plaatsen waar dat volgens de APV niet mag, meestal in woonwijken. Het college kan plaatsen aanwijzen waar het wel mag.", "art. 5:8 Model-APV", "q119ch5q"],
["apv", "Een vereniging wil op zaterdag een rommelmarkt houden op een plein. Wat geldt volgens de APV?", ["Voor het organiseren van een snuffelmarkt is een vergunning nodig.", "Een rommelmarkt is altijd vrij, zolang er geen eten wordt verkocht.", "Een rommelmarkt mag alleen op zondag worden gehouden.", "Alleen de Winkeltijdenwet is van toepassing, niet de APV."], "De APV verbiedt zonder vergunning een snuffelmarkt of rommelmarkt te organiseren die voor publiek toegankelijk is (artikel 5:23 Model-APV).", "art. 5:22 en 5:23 Model-APV", "qw5pod0"],
["apv", "Iemand verbrandt in zijn achtertuin snoeiafval en oude meubels. Wat geldt volgens de APV?", ["Het is verboden buiten een inrichting afvalstoffen te verbranden of vuur te stoken, tenzij er ontheffing is.", "Het is toegestaan, zolang het vuur in een metalen ton wordt gestookt en er een emmer water klaarstaat.", "Het is alleen verboden als er een brandweerauto in de buurt staat.", "Het is altijd toegestaan in de eigen tuin."], "De APV verbiedt buiten een inrichting afvalstoffen te verbranden of anderszins vuur te stoken (artikel 5:34 Model-APV). Er zijn uitzonderingen, zoals barbecues en vuurkorven, en het college kan ontheffing verlenen.", "art. 5:34 Model-APV", "qsaqu4w"],
// ---------- VERKEER: WVW EN RVV (DOMEIN I) ----------
["wvw", "Een fout geparkeerde auto wordt in opdracht van de gemeente weggesleept. Wie moet de kosten van het wegslepen en bewaren betalen?", ["De eigenaar of houder van het voertuig.", "De gemeente, omdat zij de opdracht gaf.", "De boa die de overtreding vaststelde.", "De eigenaar van de grond waarop de auto stond."], "De kosten van het overbrengen en bewaren van een voertuig komen voor rekening van de eigenaar of houder (artikelen 170 tot en met 174 WVW 1994). Het voertuig wordt pas na betaling teruggegeven.", "art. 170 t/m 174 WVW 1994", "q1h0ikkp"],
["wvw", "Wat verstaan we in het RVV 1990 onder parkeren?", ["Een voertuig laten stilstaan langer dan nodig is voor het in- of uitstappen of het laden en lossen.", "Een voertuig uitzetten en de sleutel uit het contact halen, ook als je erbij blijft staan of in de auto blijft zitten.", "Een voertuig neerzetten op een plek met een parkeermeter of parkeerautomaat.", "Een voertuig langer dan een uur op dezelfde plek laten staan."], "Parkeren is het laten stilstaan van een voertuig anders dan gedurende de tijd die nodig is voor en het onmiddellijk in- of uitstappen van personen of het onmiddellijk laden of lossen van goederen (artikel 1 RVV 1990).", "art. 1 RVV 1990", "qcjg5d5"],
["wvw", "Een bestuurder zet zijn auto neer op 3 meter van een kruispunt en loopt een winkel in. Wat geldt?", ["Hij overtreedt het parkeerverbod binnen 5 meter van een kruispunt.", "Hij mag daar parkeren, zolang hij binnen vijf minuten terug is bij zijn auto.", "Hij overtreedt niets, want er staat geen verkeersbord.", "Hij overtreedt alleen iets als het een voorrangskruispunt is."], "Parkeren binnen 5 meter van een kruispunt is verboden, ook zonder verkeersbord (artikel 24 RVV 1990).", "art. 24 RVV 1990", "qjbpi9j"],
["wvw", "Wat is het verschil tussen een parkeerverbod (bord E1) en een verbod stil te staan (bord E2)?", ["Bij een parkeerverbod mag je nog in- en uitstappen of laden en lossen, bij een verbod stil te staan niet.", "Er is geen verschil; beide borden betekenen dat je er nooit mag stoppen.", "Bij een parkeerverbod mag je maximaal een half uur blijven staan, bij een verbod stil te staan maximaal vijf minuten.", "Een verbod stil te staan geldt alleen 's nachts tussen 22.00 en 06.00 uur."], "Bij een parkeerverbod mag je stilstaan voor het onmiddellijk in- of uitstappen of laden en lossen. Bij een verbod stil te staan mag je het voertuig helemaal niet laten stilstaan, behalve in verband met het verkeer.", "art. 23 en 24 RVV 1990; bijlage 1 RVV 1990", "q10291c9"],
["wvw", "Een bevoegde verkeersregelaar geeft met een gebaar aan dat je moet stoppen, terwijl het verkeerslicht op groen staat. Wat moet je doen?", ["Stoppen; een aanwijzing van een bevoegd persoon gaat voor op verkeerslichten.", "Doorrijden, want het verkeerslicht staat op groen.", "Alleen stoppen als de verkeersregelaar een politie-uniform draagt.", "Alleen stoppen als er ook een verkeersbord staat dat aangeeft dat je moet stoppen."], "Weggebruikers zijn verplicht aanwijzingen op te volgen van bevoegde personen, zoals politie, aangewezen boa's en verkeersregelaars (artikel 82 RVV 1990). Een aanwijzing gaat voor op verkeerslichten, verkeersborden en verkeersregels.", "art. 82 RVV 1990", "q13v3svg"],
// ---------- BIJZONDERE WETTEN (DOMEIN I) ----------
["bijz", "Je ziet een meisje van 16 jaar in een winkelcentrum met een dichte fles wijn in haar tas. Is zij strafbaar volgens artikel 45 van de Alcoholwet?", ["Ja, een minderjarige mag op een publiek toegankelijke plaats geen alcohol aanwezig hebben.", "Nee, alleen het drinken van alcohol op straat is strafbaar, niet het bij zich hebben van een dichte fles.", "Nee, het verbod geldt alleen voor sterke drank.", "Alleen als zij jonger is dan 16 jaar."], "Artikel 45 Alcoholwet verbiedt iemand die jonger is dan 18 jaar om op voor het publiek toegankelijke plaatsen alcoholhoudende drank aanwezig te hebben, ook als de fles dicht is.", "art. 45 Alcoholwet", "qy4sui9"],
["bijz", "Een man van 19 koopt in een café bier en geeft het aan zijn vriend van 16. Welk verbod overtreedt hij?", ["Het verbod op wederverstrekking (artikel 45a Alcoholwet).", "Het verbod op hinderlijk drankgebruik (artikel 2:48 APV).", "Niets, want hij heeft het bier zelf betaald en de horecaondernemer heeft aan hem geschonken.", "Alleen de horecaondernemer is strafbaar, niet de man."], "Artikel 45a Alcoholwet verbiedt een meerderjarige om op een publiek toegankelijke plaats alcohol te verstrekken aan iemand die jonger is dan 18 jaar (wederverstrekking).", "art. 45a Alcoholwet", "qr0d7ug"],
["bijz", "Welke hoofdregel geldt volgens de Winkeltijdenwet voor de openingstijden van winkels?", ["Gesloten op zon- en feestdagen en op werkdagen vóór 06.00 en na 22.00 uur, tenzij de gemeente vrijstelling geeft.", "Winkels mogen altijd open zijn; de gemeente bepaalt alleen de openingstijden van de horeca en de markten.", "Gesloten op zaterdag en zondag, en op werkdagen na 18.00 uur.", "Gesloten op zondag tot 12.00 uur; daarna mag iedere winkel open."], "Artikel 2 Winkeltijdenwet verbiedt een winkel voor publiek geopend te hebben op zondag en op feestdagen, en op werkdagen vóór 06.00 uur en na 22.00 uur. De gemeenteraad kan bij verordening vrijstelling of ontheffing regelen (artikel 3).", "art. 2 en 3 Winkeltijdenwet", "qxp3ks"],
["bijz", "Wat verstaan we onder een winkel in de zin van de Winkeltijdenwet?", ["Een besloten ruimte waarin goederen aan particulieren te koop worden aangeboden.", "Elke plaats waar diensten worden verleend aan particulieren, zoals een kapper of een garage.", "Alleen een supermarkt of warenhuis met meer dan tien medewerkers.", "Elke marktkraam op een openbare plaats."], "Een winkel is volgens artikel 1 Winkeltijdenwet een besloten ruimte waarin goederen aan particulieren worden verkocht of te koop worden aangeboden.", "art. 1 Winkeltijdenwet", "q1k89eu9"],
["bijz", "Welke bevoegdheid heeft een opsporingsambtenaar bij een economisch delict op grond van de Wet op de economische delicten?", ["Inzage vorderen van alle zakelijke gegevens en bescheiden.", "Een verdachte zonder bevel van de rechter in voorlopige hechtenis nemen.", "Een bedrijf voor onbepaalde tijd sluiten.", "Zelf een geldboete opleggen en direct innen."], "De WED geeft opsporingsambtenaren extra bevoegdheden bij economische delicten, zoals inbeslagneming van alle vatbare voorwerpen (artikel 18), inzage vorderen van zakelijke gegevens (artikel 19), toegang tot plaatsen (artikel 20) en onderzoek van zaken en vervoermiddelen (artikelen 21 en 23).", "art. 18 t/m 23 WED", "qg015oz"],
["bijz", "Je stelt een economisch delict vast. Welke verplichting heeft iedereen volgens de Wet op de economische delicten?", ["Binnen de gestelde termijn alle medewerking verlenen die je redelijkerwijs kunt vorderen.", "Altijd een volledige bekentenis afleggen als je daarom vraagt.", "De zaak zelf schikken met de gemeente, zonder dat de rechter eraan te pas komt.", "Je toegang geven tot zijn woning, ook zonder machtiging tot binnentreden van de rechter-commissaris."], "Iedereen is verplicht de opsporingsambtenaar binnen de gestelde termijn alle medewerking te verlenen die hij redelijkerwijs kan vorderen bij het uitoefenen van zijn bevoegdheden (artikel 24a WED). De verdachte hoeft niet aan zijn eigen veroordeling mee te werken.", "art. 24a WED", "q8zr3vs"],
["bijz", "Wat verstaan we in de Omgevingswet onder een lozingsactiviteit op een oppervlaktewaterlichaam?", ["Het lozen van stoffen in oppervlaktewater, zoals een sloot, vaart of rivier.", "Het onttrekken van grondwater om een kelder of bouwput droog te houden.", "Het storten van bouwafval op een stortplaats met vergunning.", "Het varen met een motorboot op openbaar water."], "Een lozingsactiviteit op een oppervlaktewaterlichaam is het lozen van stoffen in een oppervlaktewaterlichaam, zoals een sloot, kanaal of rivier (bijlage bij artikel 1.1 Omgevingswet).", "bijlage bij art. 1.1 Omgevingswet", "qowd3o1"],
["bijz", "Een bedrijf graaft een kuil en stort er afgewerkte olie en bedrijfsafval in. Wat geldt?", ["Het storten of in de bodem brengen van bedrijfsafvalstoffen of gevaarlijke stoffen is verboden.", "Dit is toegestaan op eigen terrein, zolang het daarna wordt afgedekt met een laag schone grond.", "Dit is alleen verboden als het afval binnen 10 meter van een sloot ligt.", "Dit is alleen een probleem als de buren erover klagen."], "Het Besluit activiteiten leefomgeving (§ 3.2.14) verbiedt het storten of in de bodem brengen van bedrijfsafvalstoffen of gevaarlijke stoffen buiten een daarvoor bestemde inrichting.", "§ 3.2.14 Bal", "qclxt73"],
["bijz", "Rond een bouwplaats ligt veel afval dat van de bouwwerkzaamheden afkomstig is. Wat geldt volgens het omgevingsplan (bruidsschat)?", ["Afval en materialen van de activiteit moeten rond de locatie worden verwijderd.", "De gemeente moet het afval altijd zelf opruimen, op haar eigen kosten en binnen een week.", "Het afval mag blijven liggen tot de bouw volledig klaar is.", "Alleen omwonenden mogen het afval opruimen."], "Volgens artikel 22.53 van de bruidsschat in het omgevingsplan moeten afval en materialen die van een activiteit afkomstig zijn, rond de locatie van die activiteit worden verwijderd.", "art. 22.53 bruidsschat omgevingsplan", "q177tbyq"],
["bijz", "Je controleert een sportvisser aan een vijver. Wat moet hij volgens de Visserijwet 1963 kunnen tonen?", ["Een geldige schriftelijke toestemming van de rechthebbende, zoals de VISpas met de lijst van viswateren.", "Alleen een geldig identiteitsbewijs; verder is vissen met een hengel vrij in heel Nederland.", "Een vergunning van de gemeente voor het gebruik van de oever.", "Een bewijs dat hij lid is van een sportvereniging naar keuze."], "Wie vist in water waar het visrecht bij een ander ligt, moet een schriftelijke toestemming van de rechthebbende bij zich hebben, zoals de VISpas met lijst van viswateren, en die op verzoek tonen (artikel 23 Visserijwet 1963).", "art. 23 Visserijwet 1963", "q1yd16hw"],
["bijz", "Een ondernemer zet zijn bedrijfsafval bij het huishoudelijk afval aan de straat. Wie is hiervoor strafbaar?", ["De ondernemer die zich op deze manier van zijn bedrijfsafval ontdoet.", "De gemeente, omdat zij het afval niet direct bij de ondernemer ophaalt.", "De afvalinzamelaar die de container leegt.", "De buren die de container naast hun huis hebben staan."], "Bedrijfsafval mag niet als huishoudelijk afval worden aangeboden. Wie zich van bedrijfsafvalstoffen ontdoet op een manier die niet is toegestaan, zoals bij het huisvuil, is strafbaar (artikel 10.37 Wet milieubeheer en de Afvalstoffenverordening).", "art. 10.37 Wm; Model Afvalstoffenverordening", "q1obxd9b"],
// ---------- BEJEGENING: RUBRIC ----------
["com", "Welke afstand houd je volgens de rubric Bejegening van ExTH aan tot de persoon met wie je praat?", ["Minimaal één armlengte, en je past de afstand aan als de persoon dichterbij komt.", "Zo dichtbij mogelijk, zodat de persoon je goed kan verstaan.", "Minimaal vijf meter, zodat je altijd kunt weglopen als het gesprek uit de hand loopt.", "Dat maakt niet uit, zolang je oogcontact houdt."], "Je neemt je eigen veiligheid in acht door minimaal een armlengte afstand te houden. Voor de hoogste score benoem je dat ook en pas je de afstand aan als de persoon dichterbij komt (meeveren).", "Rubric Bejegening Domein I en IV (ExTH)", "q1fvxkla"],
["com", "Hoe leg je volgens de rubric Bejegening de situatie het best uit aan de persoon?", ["Feitelijk juist in twee tot vier zinnen, met wat er gaande is en wat het voor hem betekent.", "Zo uitgebreid mogelijk, met alle artikelen uit de wet erbij, zodat er geen vragen overblijven.", "In één woord, zodat er geen discussie ontstaat.", "Pas aan het einde van het gesprek, als hij rustig is."], "Volgens de rubric leg je de situatie feitelijk juist uit in twee tot vier zinnen. Voor de hoogste score vertel je ook wat er gaande is en wat dit voor de betrokkene betekent.", "Rubric Bejegening Domein IV (ExTH)", "q1k79fw4"],
// ---------- BEJEGENING: RUBRIC ----------
["agr", "Hoe reageer je volgens de rubric Bejegening professioneel op boosheid van de persoon?", ["Met een gevoelsreflectie, zoals 'Ik zie dat u boos bent, omdat…', en vragen over die emotie.", "Door meteen een grens te stellen, ook als de persoon alleen boos of gefrustreerd is.", "Door mee te gaan in zijn boosheid, zodat hij zich begrepen voelt.", "Door de emotie te negeren en direct over de regels te praten."], "Je benoemt de emotie met een gevoelsreflectie ('ik zie / hoor / merk dat u…') en stelt aanvullende vragen. Een grens stellen terwijl de persoon alleen boos of gefrustreerd is, levert in de rubric juist punten op het laagste niveau op.", "Rubric Bejegening Domein I en IV (ExTH)", "q1aavt0k"],
["agr", "Wanneer doe je volgens de rubric Bejegening het best een voorstel voor een alternatief?", ["Nadat de emotie van de persoon is gezakt, en dan een realistisch alternatief.", "Zo snel mogelijk, ook als de persoon nog erg boos is, zodat het gesprek kort blijft.", "Nooit; alternatieven bieden is niet de taak van een boa.", "Alleen als de persoon zelf om een alternatief vraagt."], "Je geeft de persoon eerst ruimte om emotie te tonen en zijn verhaal te doen. Pas als de emotie is gereguleerd, geef je realistische alternatieven; voor de hoogste score herhaal je daarbij wat de persoon over zijn situatie zei.", "Rubric Bejegening Domein I en IV (ExTH)", "qhahd6x"],
// ---------- BEJEGENING: RUBRIC ----------
["prof", "Hoe rond je volgens de rubric Bejegening het gesprek professioneel af?", ["Je herhaalt de afspraken, vraagt of er nog vragen zijn en groet de persoon.", "Je biedt je excuses aan voor je optreden, zodat de persoon tevreden vertrekt.", "Je laat de persoon weglopen zodra de bon is uitgeschreven.", "Je benoemt nog eens hoe vervelend de escalatie eerder in het gesprek was."], "Professioneel afronden: gemaakte afspraken herhalen, vragen of de persoon nog vragen heeft en die beantwoorden, en groeten. Excuses maken voor je optreden of de eerdere escalatie benoemen past daar niet bij.", "Rubric Bejegening Domein I en IV (ExTH)", "q1qzmnhx"],
// ---------- BEJEGENING: RUBRIC ----------
["com", "Je spreekt een verdachte aan op een strafbaar feit. Wat hoort er volgens de rubric Bejegening Domein IV bij het melden van het feit?", ["Het juiste strafbare feit benoemen, proces-verbaal aanzeggen en staande houden kunnen uitleggen.", "Eerst een uitgebreid praatje maken over het weer en het feit pas aan het einde van het gesprek noemen.", "Alleen zeggen dat hij een bon krijgt, zonder het feit te noemen.", "De verdachte vragen of hij zelf vindt dat hij een bon verdient."], "Voor de hoogste score houd je de verdachte staande en benoem je dat, benoem je het juiste strafbare feit, zeg je duidelijk en vanuit een ik-boodschap proces-verbaal aan, en kun je uitleggen wat staande houden betekent: de identiteit vaststellen om een proces-verbaal op te maken.", "Rubric Bejegening Domein IV, casus strafbaar feit (ExTH)", "qssalwx"],
["com", "De persoon heeft al gezegd dat een voorgestelde oplossing voor hem geen optie is. Wat doe je volgens de rubric Bejegening?", ["Je komt niet opnieuw met die suggestie en vraagt gericht door.", "Je herhaalt de suggestie tot hij er toch mee instemt.", "Je beëindigt het gesprek, want hij werkt niet mee.", "Je doet dezelfde suggestie nog eens met andere woorden."], "De rubric beoordeelt luisteren, samenvatten en doorvragen. Wie voor de tweede keer komt met een suggestie die de persoon al heeft afgewezen, scoort op het laagste niveau.", "Rubric Bejegening Domein I en IV (ExTH)", "qvzssgt"],
// ---------- BEJEGENING: RUBRIC ----------
["prof", "Welke taal gebruik je volgens de rubric Bejegening tegenover de persoon?", ["Begrijpelijke Nederlandse woorden zonder vakjargon, aansluitend bij zijn eigen woorden.", "Zoveel mogelijk wetsartikelen en juridische termen, zodat duidelijk is dat je weet waar je het over hebt.", "Straattaal, om op hetzelfde niveau te komen als de persoon.", "Engels, zodat iedereen je kan verstaan."], "Je gebruikt geen vakjargon, of je legt het correct uit. Voor de hoogste score sluit je aan bij de woorden en de taal die de persoon zelf gebruikt.", "Rubric Bejegening Domein IV (ExTH)", "q3aycb4"],
["prof", "Je werkt aan een balie en een burger vraagt of je kunt regelen dat zijn boete vervalt. Wat doe je volgens de rubric Bejegening Domein I?", ["Je doet geen beloftes die je niet kunt nakomen en geeft juiste informatie.", "Je belooft dat je ernaar zult kijken, zodat hij tevreden en rustig vertrekt.", "Je zegt toe dat de boete vervalt als hij nu rustig blijft.", "Je verwijst hem door zonder uit te leggen waarom."], "Bij de casus balie dienstverlening scoor je op het laagste niveau als je beloftes doet die niet kunnen worden nagekomen. Je geeft juiste informatie en handelt integer.", "Rubric Bejegening Domein I, casus balie dienstverlening (ExTH)", "qykm9d9"],
["prof", "Uit welke casussen bestaat het praktijkexamen Bejegening in domein IV?", ["Twee casussen: een aanwijzing en een strafbaar feit.", "Drie casussen: een calamiteit, een aanwijzing en balie dienstverlening.", "Eén casus: een verhoor van een verdachte.", "Vier casussen, waarvan je er twee mag kiezen."], "In domein IV bestaat het examen Bejegening uit twee casussen (een aanwijzing en een strafbaar feit) in 30 minuten. In domein I zijn het drie casussen: calamiteit, aanwijzing en balie dienstverlening. Elke casus moet minimaal voldoende zijn.", "Toetsmatrijs Bejegening Domein I en IV (ExTH)", "q1m0savq"],
// ---------- WAARNEMING EN VERSLAGLEGGING: RUBRIC ----------
["waa", "Hoeveel spel- en taalfouten mag je rapportage volgens de rubric Waarneming en verslaglegging Domein IV maximaal bevatten voor de punten op taal?", ["Maximaal zes.", "Maximaal twee.", "Maximaal tien.", "Geen enkele."], "De rubric Domein IV geeft 5 punten als de rapportage maximaal zes spel- of taalfouten bevat. Bij meer fouten krijg je voor dit criterium 0 punten.", "Rubric Waarneming en verslaglegging Domein IV v2.1 (ExTH)", "q1kpbgi7"],
["waa", "Wat is het gevolg als je rapportage meer dan twee foutieve waarnemingen bevat?", ["Je verliest de 10 punten voor het criterium 'maximaal twee foutieve waarnemingen'.", "Er gebeurt niets; foutieve waarnemingen tellen niet mee als de rest van het verslag goed is.", "Je examen wordt direct ongeldig verklaard.", "Je krijgt een extra film om opnieuw te bekijken."], "Een van de algemene criteria is dat de rapportage in totaal maximaal twee foutieve waarnemingen bevat; dat levert 10 punten op. Bij meer foutieve waarnemingen krijg je voor dit criterium 0 punten.", "Rubric Waarneming en verslaglegging Domein IV v2.1 (ExTH)", "q14gnc2j"],
["waa", "Welke onderdelen van de rubric Waarneming en verslaglegging moeten elk minimaal de helft van de punten scoren om te kunnen slagen?", ["De aanvangssituatie, de gebeurtenissen en de specificaties.", "De spelling, de chronologie en de lengte van het verslag in woorden.", "Alleen de redenen van wetenschap.", "Geen; alleen het totaal van 70 punten telt."], "De criteria aanvangssituatie, gebeurtenissen en specificaties zijn voorwaardelijk: elk moet minimaal 50% scoren. Daarnaast heb je minimaal 70 van de 100 punten nodig voor een voldoende en 85 voor goed.", "Rubric Waarneming en verslaglegging Domein IV v2.1 (ExTH)", "q45o6hi"],
["waa", "Welk onderdeel levert in de rubric Waarneming en verslaglegging Domein IV de meeste punten op?", ["De beschrijving van de gebeurtenissen: wie deed wat, hoe, waarmee, wie zei wat en met welke gevolgen.", "De beschrijving van het weer, de lichtval en de geluiden tijdens het bekijken van de film.", "Het aantal woorden van het verslag.", "De opmaak en de lay-out van het sjabloon."], "De gebeurtenissen leveren tot 47 punten op. De aanvangssituatie levert 10 punten op, de specificaties (signalementen) 8, en de algemene criteria samen 35.", "Rubric Waarneming en verslaglegging Domein IV v2.1 (ExTH)", "q1uv91lb"],
// ---------- PROCES-VERBAAL ----------
["pv", "Met welke zin begint het examensjabloon Waarneming en verslaglegging OV na je gegevens?", ["'…verklaar het volgende;' waarna je je waarnemingen vastlegt.", "'Geachte heer, mevrouw,' gevolgd door een korte inleiding.", "'Naar aanleiding van uw verzoek bericht ik u het volgende.'", "'Op een mooie dag liep ik door het station.'"], "In het sjabloon vul je in: 'Ik, [naam], [functie], in dienst van de [organisatie], [afdeling], [nummer akte van beëdiging], verklaar het volgende;'. Daarna leg je je waarnemingen vast. Onderaan staat dat het verslag is opgemaakt door een buitengewoon opsporingsambtenaar, met naam en datum.", "Sjabloon Waarneming en verslaglegging OV v1.2 (ExTH)", "qnex4dj"],
// ---------- JEUGD (FUNCTIEGERICHTE TRAINING) ----------
["jgd", "Je spreekt een groep jongeren aan op overlast. Welke aanpak werkt in de communicatie met jongeren meestal het best?", ["Rustig en duidelijk zijn, de jongeren serieus nemen en de leider van de groep apart aanspreken.", "Hard optreden tegen de hele groep tegelijk, zodat iedereen schrikt en direct vertrekt.", "Zo veel mogelijk jongerentaal gebruiken om erbij te horen.", "Direct de ouders bellen, voordat je met de jongeren praat."], "Jongeren reageren beter op een rustige, duidelijke en respectvolle benadering. In een groep is het vaak verstandig de leider apart aan te spreken, zodat niemand gezichtsverlies lijdt tegenover de anderen.", "Functiegerichte training Jeugd (ExTH-geaccrediteerd)", "qjp58pe"],
["jgd", "Waarom is het belangrijk om bij een jongere die je aanspreekt, rekening te houden met zijn ontwikkeling?", ["Jongeren overzien gevolgen vaak minder goed en reageren sneller impulsief.", "Jongeren zijn wettelijk nooit verantwoordelijk voor hun gedrag, ook niet boven de 12 jaar.", "Jongeren mogen niet worden aangesproken zonder hun ouders erbij.", "Jongeren hoeven zich niet aan de APV te houden."], "Het brein van jongeren is nog in ontwikkeling: ze overzien gevolgen minder goed en reageren sneller impulsief of vanuit groepsdruk. Duidelijke uitleg en het bieden van een uitweg zonder gezichtsverlies helpen de-escaleren.", "Functiegerichte training Jeugd (ExTH-geaccrediteerd)", "q12iuowl"],
["jgd", "Welke functiegerichte trainingen zijn in domein IV door ExTH geaccrediteerd?", ["AVG en Wpg, Opmaken proces-verbaal en Communicatie met jeugdigen.", "Wijkgericht werken, Cultureel vakmanschap en Jeugdboa.", "Alleen Opmaken proces-verbaal.", "Bejegening, Waarneming en verslaglegging en Wet- en regelgeving."], "Volgens het overzicht van ExTH (versie 20 augustus 2026) zijn in domein IV geaccrediteerd: AVG en Wpg, Opmaken proces-verbaal en Communicatie met jeugdigen. In domein I zijn dat AVG en Wpg, Opmaken proces-verbaal, Wijkgericht werken, Jeugdboa en Cultureel vakmanschap.", "Geaccrediteerde functiegerichte trainingen Domein I en IV (ExTH, 20-8-2026)", "qauhu7d"],
["jgd", "Hoeveel studiebelastingsuren omvat een functiegerichte training in de PHB?", ["24 studiebelastingsuren.", "8 studiebelastingsuren.", "50 studiebelastingsuren.", "120 studiebelastingsuren."], "Volgens de examenprogramma's van domein I en IV omvat de functiegerichte training 24 studiebelastingsuren. Er is geen examen: de training is behaald als je hem volgens de accreditatievoorwaarden hebt afgerond.", "Examenprogramma PHB Domein I 2023-2028 en Domein IV 2025-2028 (ExTH)", "q1y5si6"],
// ---------- AANVULLING 1.6.1: toetstermen met te weinig vragen ----------
["bev", "Waarom stelt een boa bij het opmaken van een proces-verbaal de identiteit van de verdachte vast?", ["Om zeker te weten tegen wie het proces-verbaal is opgemaakt, zodat de zaak kan worden afgedaan of vervolgd.", "Om te controleren of de verdachte een vaste woon- of verblijfplaats heeft in de gemeente waar hij werkt.", "Om de gegevens van de verdachte te kunnen doorgeven aan zijn werkgever, zodat die maatregelen kan nemen.", "Om voor de gemeente een persoonlijk profiel van overlastgevers op te bouwen dat later kan worden gebruikt."], "Gegevens worden in het strafrecht verzameld voor de opsporing en vervolging van strafbare feiten. De identiteit van de verdachte moet vaststaan, zodat het proces-verbaal of de strafbeschikking tegen de juiste persoon wordt opgemaakt.", "art. 27a Sv; art. 3 Wpg", "q1flncs3"],
["bev", "Mag een boa de gegevens die hij bij een controle heeft verzameld, gebruiken voor een ander doel dan waarvoor hij ze verzamelde?", ["Nee, gegevens mogen alleen worden verwerkt voor het doel waarvoor ze zijn verzameld, tenzij de wet iets anders toestaat.", "Ja, zolang de gegevens binnen de eigen gemeente of bij de eigen werkgever van de boa blijven.", "Ja, als de persoon bij de controle niet uitdrukkelijk heeft gezegd dat hij daartegen bezwaar heeft.", "Alleen als de gegevens ouder zijn dan een jaar, omdat ze dan niet meer als persoonsgegevens gelden."], "Gegevens die een boa in het kader van de opsporing verwerkt, vallen onder de Wet politiegegevens. Ze mogen alleen worden verwerkt voor zover dat nodig is voor het doel waarvoor ze zijn verzameld (doelbinding). Verstrekken voor een ander doel mag alleen als de wet dat regelt.", "art. 3 en 4 Wpg", "q9qyok7"],
["bst", "Wat is een besluit volgens de Algemene wet bestuursrecht?", ["Een schriftelijke beslissing van een bestuursorgaan, inhoudende een publiekrechtelijke rechtshandeling.", "Elke mondelinge of schriftelijke afspraak die de gemeente maakt met een inwoner of een bedrijf.", "Een uitspraak van de bestuursrechter over een bezwaar van een burger tegen de gemeente.", "Een beslissing van de gemeenteraad; beslissingen van de burgemeester of het college horen daar niet bij."], "Volgens artikel 1:3 Awb is een besluit een schriftelijke beslissing van een bestuursorgaan, inhoudende een publiekrechtelijke rechtshandeling. Voorbeelden zijn een vergunning, een last onder dwangsom en een bestuurlijke boete. Tegen een besluit staat bezwaar en beroep open.", "art. 1:3 Awb", "q1euod9g"],
["bst", "Een ondernemer is het niet eens met een besluit van het college van burgemeester en wethouders. Wat kan hij doen?", ["Binnen zes weken bezwaar maken bij het college dat het besluit heeft genomen.", "Direct aangifte doen bij de politie tegen het college wegens misbruik van zijn macht.", "Binnen twee weken in hoger beroep gaan bij de Hoge Raad der Nederlanden in Den Haag.", "Een klacht indienen bij de officier van justitie, die het besluit van het college kan vernietigen."], "Tegen een besluit kan een belanghebbende eerst bezwaar maken bij het bestuursorgaan dat het besluit nam. De termijn is zes weken. Pas na de beslissing op bezwaar staat beroep open bij de bestuursrechter.", "art. 6:7, 7:1 en 8:1 Awb", "qtz580r"],
["apv", "Wat is volgens artikel 2:1 van de Model-APV verboden op een openbare plaats?", ["Deelnemen aan een samenscholing, ordeverstoring veroorzaken of deelnemen aan ongeregeldheden.", "Met meer dan drie personen tegelijk op een plein, in een park of bij een winkelcentrum staan.", "Hardop praten of zonder koptelefoon naar muziek luisteren na tien uur 's avonds.", "Op een bankje zitten zonder dat je iets koopt bij een van de winkels of cafés in de buurt."], "Artikel 2:1 van de Model-APV verbiedt op een openbare plaats deel te nemen aan een samenscholing, ordeverstoring te veroorzaken of deel te nemen aan ongeregeldheden. Gewoon samen op straat staan is niet verboden; het gaat om groepen die de openbare orde verstoren.", "art. 2:1 Model-APV", "q1m229hf"],
["apv", "Bij ongeregeldheden op straat beveelt de politie de omstanders om door te lopen. Wat geldt?", ["Iedereen die aanwezig is, moet het bevel opvolgen, ook wie zelf niet meedoet aan de ongeregeldheden.", "Alleen wie zelf actief meedoet aan de ongeregeldheden, hoeft het bevel van de politie op te volgen.", "Het bevel geldt alleen als de burgemeester het vooraf schriftelijk heeft bevestigd en bekendgemaakt.", "Omstanders mogen blijven staan zolang zij geen foto's of filmpjes van de ongeregeldheden maken."], "Bij samenscholing, ordeverstoring of ongeregeldheden is volgens de APV iedereen die aanwezig is verplicht de bevelen van de politie op te volgen, bijvoorbeeld om door te lopen. Wie dat niet doet, overtreedt de APV.", "art. 2:1 Model-APV", "q10mq9tz"],
["apv", "Een bezoeker van een festival in het park plast achter een boom, terwijl verderop een openbaar urinoir staat. Wat geldt?", ["Hij overtreedt het verbod om op een openbare plaats je behoefte te doen buiten een toilet of urinoir.", "Hij overtreedt niets, omdat hij achter een boom staat en andere bezoekers hem niet kunnen zien.", "Hij overtreedt alleen iets als er op dat moment kinderen in de buurt van die boom aanwezig zijn.", "Hij overtreedt alleen iets als de organisator van het festival klacht indient bij de gemeente."], "Artikel 4:8 van de Model-APV verbiedt op of aan de weg en op andere openbare plaatsen je behoefte te doen, anders dan in een toilet of urinoir. Of iemand gezien wordt, maakt niet uit.", "art. 4:8 Model-APV", "q1k9vss7"],
["apv", "Waar mag je volgens artikel 4:8 van de Model-APV op een openbare plaats je behoefte doen?", ["Alleen in een toilet of urinoir.", "Overal waar geen verbodsbord staat.", "Op elke plek buiten de bebouwde kom.", "Op straat, als het na middernacht is."], "Het verbod in artikel 4:8 Model-APV geldt op of aan de weg en op andere openbare plaatsen. Alleen een toilet of urinoir is toegestaan. Er hoeft geen bord te staan en het tijdstip maakt niet uit.", "art. 4:8 Model-APV", "qvc18xh"],
["wvw", "Wanneer krijgt de eigenaar een voertuig terug dat op last van de gemeente is weggesleept?", ["Nadat de kosten van het overbrengen en de bewaring zijn betaald.", "Direct, want de gemeente stuurt de rekening later naar de eigenaar.", "Pas nadat de kantonrechter de zaak heeft behandeld.", "Na een wachttijd van zeven dagen, ongeacht of er is betaald."], "Een weggesleept voertuig wordt bewaard op een plaats die de gemeente aanwijst. De eigenaar of houder krijgt het terug nadat hij de kosten van het overbrengen en de bewaring heeft betaald. De hoogte van de kosten staat in de wegsleepverordening.", "art. 170 t/m 172 WVW 1994; wegsleepverordening", "qor7f90"],
["wvw", "Op welke wegen mag een fout geparkeerd voertuig op grond van de Wegenverkeerswet worden weggesleept?", ["Op wegen die de gemeente daarvoor in haar wegsleepverordening heeft aangewezen.", "Op elke weg in Nederland, zonder dat de gemeente daarover regels hoeft te maken.", "Alleen op autosnelwegen en provinciale wegen buiten de bebouwde kom.", "Alleen op privéterrein, als de eigenaar van het terrein daarom vraagt."], "De Wegenverkeerswet en het Besluit wegslepen van voertuigen regelen het wegslepen. De gemeenteraad wijst in een wegsleepverordening de wegen aan waar dit mag en regelt de bewaarplaats en de kosten.", "art. 170 WVW 1994; Besluit wegslepen van voertuigen", "q1cpro96"],
["wvw", "Langs de rand van de rijbaan staat een gele onderbroken streep. Wat betekent dit?", ["Je mag daar niet parkeren; kort stilstaan om in of uit te stappen of te laden en te lossen mag wel.", "Je mag daar niet stilstaan, ook niet om iemand in of uit te laten stappen.", "Je mag daar alleen parkeren met een parkeerschijf, en hoogstens twee uur.", "De streep heeft geen betekenis voor parkeren, maar geeft een fietsstrook aan."], "Een gele onderbroken streep langs de rand van de rijbaan betekent een parkeerverbod. Stilstaan om direct in of uit te stappen of te laden en te lossen is wel toegestaan. Een gele doorgetrokken streep betekent een verbod stil te staan.", "art. 24 en 23 RVV 1990", "qfg8snr"],
["wvw", "Wat is volgens het RVV 1990 de rangorde van verkeersvoorschriften, van hoog naar laag?", ["Aanwijzingen van bevoegde personen, verkeerslichten, verkeerstekens, verkeersregels.", "Verkeersregels, verkeerstekens, verkeerslichten, aanwijzingen van bevoegde personen.", "Verkeerslichten, aanwijzingen van bevoegde personen, verkeersregels, verkeerstekens.", "Verkeerstekens, verkeerslichten, verkeersregels, aanwijzingen van bevoegde personen."], "Artikel 63 RVV 1990 bepaalt de rangorde: aanwijzingen van bevoegde personen gaan voor verkeerslichten, verkeerslichten gaan voor verkeerstekens, en verkeerstekens gaan voor de verkeersregels.", "art. 63 RVV 1990", "q1f3ogjo"],
["wvw", "Een automobilist negeert het stopteken van een boa die bevoegd is om aanwijzingen in het verkeer te geven. Welk voorschrift overtreedt hij?", ["Artikel 82 RVV 1990: weggebruikers moeten de aanwijzingen van bevoegde personen opvolgen.", "Artikel 24 RVV 1990: het parkeren binnen vijf meter van een kruispunt.", "Artikel 447e Sr: het niet tonen van een identiteitsbewijs op vordering.", "Artikel 2:1 APV: het deelnemen aan een samenscholing of ordeverstoring."], "Weggebruikers zijn verplicht de aanwijzingen op te volgen die bevoegde personen met gebaren of anders geven (artikel 82 RVV 1990). Een stopteken van een daartoe bevoegde boa is zo'n aanwijzing.", "art. 82 RVV 1990", "qeqg0gd"],
["bijz", "Een slijter verkoopt een fles wodka aan een jongen zonder naar zijn leeftijd te vragen. De jongen blijkt 17 jaar. Wat overtreedt de slijter?", ["Het verbod om alcohol te verstrekken zonder vast te stellen dat de koper 18 jaar of ouder is.", "Niets, want de jongen heeft zelf niets over zijn leeftijd gezegd en had dat moeten doen.", "Het verbod op wederverstrekking, omdat de jongen de fles vermoedelijk met vrienden deelt.", "Niets, want in een slijterij mag sterke drank vanaf 16 jaar aan klanten worden verkocht."], "Artikel 20 van de Alcoholwet verbiedt alcohol te verstrekken aan iemand van wie niet is vastgesteld dat hij 18 jaar of ouder is. De verkoper moet de leeftijd dus zelf vaststellen, bijvoorbeeld met een identiteitsbewijs.", "art. 20 Alcoholwet", "qtaelqg"],
["bijz", "Wat is volgens de Alcoholwet verboden voor een horecaondernemer?", ["Alcohol schenken aan iemand die kennelijk dronken is.", "Alcohol schenken aan een gast die niets te eten bestelt bij zijn drankje.", "Na middernacht alcohol schenken zonder toestemming van de politie.", "Een gast meer dan drie glazen bier binnen een uur te schenken."], "De Alcoholwet verbiedt alcohol te verstrekken aan iemand die in kennelijke staat van dronkenschap is. Ook mag de ondernemer zo iemand niet toelaten in zijn zaak.", "art. 20 Alcoholwet", "q1t0aavt"],
["bijz", "Welk bestuursorgaan is bij de Omgevingswet meestal bevoegd voor toezicht en handhaving op activiteiten in de gemeente?", ["Het college van burgemeester en wethouders.", "De burgemeester alleen, als hoofd van de openbare orde.", "De minister van Infrastructuur en Waterstaat.", "De officier van justitie van het arrondissement."], "Bij de Omgevingswet is het bestuursorgaan dat bevoegd is voor de vergunning, ook bevoegd voor toezicht en handhaving. Voor de meeste activiteiten in de gemeente, zoals de regels van het omgevingsplan, is dat het college van burgemeester en wethouders.", "art. 18.2 Omgevingswet", "q1q5zwqh"],
["bijz", "Van wie heeft een sportvisser toestemming nodig om in een binnenwater te mogen vissen?", ["Van de rechthebbende op het visrecht, zoals een hengelsportvereniging.", "Van de gemeente, via een visvergunning die het gemeentehuis afgeeft.", "Van de Rijksdienst voor het Wegverkeer, via een visakte op naam.", "Van niemand, want vissen met één hengel is in alle binnenwateren vrij."], "Voor vissen in binnenwateren is schriftelijke toestemming nodig van degene die het visrecht heeft, meestal een hengelsportvereniging of federatie. In de praktijk is dat de VISpas met de lijst van viswateren.", "art. 21 Visserijwet 1963", "qz1ecuq"],
["bijz", "Een sportvisser kan bij een controle zijn schriftelijke toestemming niet laten zien. Wat geldt?", ["Hij overtreedt de Visserijwet: wie vist, moet de toestemming bij zich hebben en op verzoek tonen.", "Niets, als hij de toestemming binnen een week alsnog laat zien op het politiebureau.", "Niets, want de Visserijwet geldt alleen voor beroepsvissers met een boot en netten.", "Hij overtreedt alleen iets als hij op dat moment al een vis heeft gevangen."], "Wie vist, moet de schriftelijke toestemming bij zich hebben en die op eerste vordering laten zien aan een opsporingsambtenaar. Kan hij dat niet, dan overtreedt hij de Visserijwet 1963.", "art. 21 en 23 Visserijwet 1963", "q1b2yx3j"],
["bijz", "Een ondernemer laat zijn bedrijfsafval ophalen door een buurman met een aanhanger, die geen erkende inzamelaar is. Wat geldt?", ["De ondernemer overtreedt het verbod om bedrijfsafval af te geven aan iemand die daar niet toe bevoegd is.", "Alleen de buurman is strafbaar, omdat de ondernemer zijn afval netjes heeft laten ophalen.", "Niets, zolang de buurman het afval daarna zelf naar een milieustraat van de gemeente brengt.", "Niets, want de Wet milieubeheer geldt alleen voor gevaarlijk afval, zoals chemicaliën en olie."], "Wie zich van bedrijfsafval ontdoet, mag dat alleen afgeven aan iemand die daarvoor bevoegd is, zoals een erkende inzamelaar of verwerker. Geeft de ondernemer het af aan een ander, dan overtreedt hij artikel 10.37 van de Wet milieubeheer.", "art. 10.37 Wm", "qrg0r4"],
["bijz", "Wat is volgens artikel 10.2 van de Wet milieubeheer verboden met afvalstoffen buiten een inrichting?", ["Je ervan ontdoen door ze te storten, in de bodem te brengen of te verbranden.", "Ze bewaren in een afgesloten container op eigen terrein tot de ophaaldag.", "Ze scheiden in plastic, papier en restafval voordat ze worden opgehaald.", "Ze zelf naar de milieustraat van de gemeente brengen met je eigen auto."], "Artikel 10.2 van de Wet milieubeheer verbiedt je van afvalstoffen te ontdoen door ze buiten een inrichting te storten, op of in de bodem te brengen of te verbranden. Bewaren, scheiden en zelf naar de milieustraat brengen zijn juist toegestaan.", "art. 10.2 Wm", "qju4vhp"],
["vrij", "Wie mag een verdachte aanhouden bij ontdekking op heterdaad?", ["Iedereen, dus ook een burger zonder opsporingsbevoegdheid.", "Alleen opsporingsambtenaren, zoals politieagenten en boa's.", "Alleen de officier van justitie of een hulpofficier van justitie.", "Alleen een boa met geweldsbevoegdheid en handboeien."], "Bij ontdekking op heterdaad is ieder bevoegd de verdachte aan te houden (artikel 53 Sv). Een burger moet de verdachte daarna wel direct overdragen aan een opsporingsambtenaar.", "art. 53 Sv", "q10m6npf"],
["vrij", "Aan wie moet een boa een aangehouden verdachte voorgeleiden?", ["Aan de officier van justitie of een hulpofficier van justitie.", "Aan de rechter-commissaris bij de rechtbank in het arrondissement.", "Aan de korpschef van de politie of diens plaatsvervanger.", "Aan de burgemeester van de gemeente waar hij is aangehouden."], "Een opsporingsambtenaar die een verdachte aanhoudt, geleidt hem onverwijld voor aan de officier van justitie of een hulpofficier van justitie. In de praktijk is dat meestal een hulpofficier van justitie op het politiebureau.", "art. 53 lid 3 en 54 Sv", "q972zm0"],
["vrij", "Hoe snel moet een aangehouden verdachte worden voorgeleid?", ["Onverwijld, dus zonder onnodige vertraging.", "Binnen drie dagen na de aanhouding, als het om een misdrijf gaat.", "Pas nadat de boa de verdachte zelf heeft verhoord over het feit.", "Binnen 24 uur, waarbij de nachtelijke uren niet worden meegeteld."], "De wet schrijft voor dat een aangehouden verdachte onverwijld wordt voorgeleid, zodat de officier of hulpofficier van justitie meteen kan toetsen of de aanhouding terecht is en wat er verder gebeurt.", "art. 53 lid 3 en 54 Sv", "q7xg7n7"],
["amb", "Je wordt als boa tijdens je werk bedreigd en doet aangifte. Welk adres mag je op de aangifte laten zetten?", ["Het adres van je werkgever, zodat de verdachte je huisadres niet te zien krijgt.", "Alleen je eigen huisadres, omdat een aangifte anders niet geldig is.", "Het adres van de rechtbank waar de zaak later wordt behandeld.", "Geen adres, want een aangifte van een boa is altijd anoniem."], "Werknemers met een publieke taak, zoals boa's, mogen bij een aangifte domicilie kiezen op het adres van hun werkgever. Zo komt hun huisadres niet in het dossier dat de verdachte kan inzien.", "Eenduidige Landelijke Afspraken (ELA); art. 163 Sv", "q1cy8eff"],
["amb", "Wat is volgens de Eenduidige Landelijke Afspraken het uitgangspunt bij de strafeis voor bedreiging of geweld tegen een boa?", ["Het openbaar ministerie eist een zwaardere straf dan bij hetzelfde feit tegen een gewone burger.", "Het openbaar ministerie seponeert de zaak als de boa geen zichtbaar letsel heeft opgelopen.", "Het openbaar ministerie eist dezelfde straf, omdat een boa wettelijk geen ambtenaar is.", "Het openbaar ministerie behandelt de zaak alleen als ook de werkgever aangifte doet."], "Volgens de Eenduidige Landelijke Afspraken van politie en openbaar ministerie krijgen zaken van agressie en geweld tegen werknemers met een publieke taak voorrang, en eist het openbaar ministerie een hogere straf dan bij hetzelfde feit tegen een gewone burger.", "Eenduidige Landelijke Afspraken (ELA); Aanwijzing kader voor strafvordering", "q1lpvl25"]
];
